{
  "schema": "hepta-effective-config-v1",
  "scope": "loaded_runtime_policy_capabilities",
  "semantics": "Configured flags and counts only; target reachability, path availability, specific argument authorization and existing sudo authorization are not verified.",
  "redaction": "capabilities_and_counts_only",
  "policy_mutation_supported": false,
  "target_probe_performed": false,
  "controller": {
    "workspace_root_count": 1,
    "file_workspace_roots_configured": true
  },
  "hosts": [
    {
      "alias": "pocket4",
      "platform": "linux",
      "execution_mode": "operator",
      "permissions": {
        "allow_execute": true,
        "allow_pty": true,
        "allow_write": true,
        "allow_job_network": true,
        "allow_detached_fallback": true
      },
      "file_api": {
        "read_root_count": 1,
        "write_root_count": 1,
        "read_paths_configured": true,
        "write_paths_authorized_and_configured": true
      },
      "named_privileged_action_count": 0,
      "checkpoint_pin_configured": false
    }
  ],
  "limits": {
    "maximum_summary_host_entries": 256,
    "maximum_summary_response_bytes": 262144
  }
}
